#!/usr/bin/env python3
"""Parse approved GitHub Issue body ([Цена РФ] or [Ревизия]) and apply structured update to JSON data."""

import argparse
import datetime
import json
import os
import re


def parse_issue_fields(body: str) -> dict:
    """Extract ### Heading\n\nValue pairs generated by GitHub YAML Issue Forms."""
    fields = {}
    blocks = re.split(r"(?m)^###\s+", body or "")
    for blk in blocks[1:]:
        lines = blk.strip().splitlines()
        if not lines:
            continue
        key = lines[0].strip().lower()
        val = "\n".join(lines[1:]).strip()
        fields[key] = val
    return fields


def main():
    parser = argparse.ArgumentParser(description="Apply approved GitHub Issue update to prices_rf_snapshot.json")
    parser.add_argument("--body", required=True, help="Raw GitHub Issue markdown body")
    parser.add_argument("--snapshot", default="data/prices_rf_snapshot.json")
    args = parser.parse_args()

    fields = parse_issue_fields(args.body)
    model = next((v for k, v in fields.items() if "модел" in k), "")
    price_raw = next((v for k, v in fields.items() if "цена" in k), "")
    channel = next((v for k, v in fields.items() if "канал" in k), "")
    url = next((v for k, v in fields.items() if "ссылк" in k), "")

    digits = re.sub(r"\D", "", price_raw)
    if not model or not digits:
        print("No structured price update fields detected; skipping.")
        return

    price_rub = int(digits)
    with open(args.snapshot, "r", encoding="utf-8") as fp:
        snap = json.load(fp)

    is_retail = "офлайн" in channel.lower() or "dns" in channel.lower() or "ситилинк" in channel.lower()
    today = datetime.date.today().isoformat()
    existing = next((x for x in snap.get("items", []) if x.get("model_match", "").lower() == model.lower()), None)
    if existing:
        if is_retail:
            existing["retail_rf_rub"] = price_rub
        else:
            existing["mp_rf_rub"] = price_rub
        existing["min_90d_rub"] = min(existing.get("min_90d_rub", price_rub), price_rub)
        if url.startswith("http"):
            existing["url"] = url
        existing["checked_at"] = today
    else:
        snap.setdefault("items", []).append({
            "model_match": model,
            "sku_rf": "",
            "retail_rf_rub": price_rub if is_retail else 0,
            "mp_rf_rub": price_rub if not is_retail else price_rub,
            "min_90d_rub": price_rub,
            "store": channel or "Сообщество РФ",
            "url": url,
            "checked_at": today,
        })

    snap["updated_at"] = today
    with open(args.snapshot, "w", encoding="utf-8") as fp:
        json.dump(snap, fp, ensure_ascii=False, indent=2)
    print(f"Applied community price update for '{model}': {price_rub} RUB ({channel})")


if __name__ == "__main__":
    main()
